sent_uci_id = False
for line in sys.stdin:
    line = line.strip()
    if line == 'uci':
        send('id name Resigner')
        send('id author OpenAI')
        send('uciok')
    elif line == 'isready':
        send('readyok')
    elif line.startswith('setoption'):
        # Ignore any option settings
        continue
    elif line.startswith('position'):
        # Ignore; we don't need to keep track of board state for our purpose
        continue
    elif line.startswith('ucinewgame'):
        continue
    elif line.startswith('go'):
        # Always claim a big eval favouring Black and output a null bestmove
        send('info depth 1 score cp -10000')
        send('bestmove 0000')
    elif line == 'quit':
        break
    # Silently ignore all other commands
