        send('id author OpenAI')
        send('uciok')
    elif cmd == 'isready':
        send('readyok')
    elif cmd.startswith('position'):
        # We ignore the position completely – we will resign anyway.
        pass
    elif cmd.startswith('go'):
        # Claim a hopeless score for White and return the null move.
        send('info depth 1 score cp -10000')
        send('bestmove 0000')
    elif cmd == 'ucinewgame':
        continue
    elif cmd == 'quit':
        break
